from pydantic import BaseModel, ConfigDict

from test_support.browser_handoff.constants import CHECKPOINT, RUN_ID, SENTINEL_VALUE
from test_support.browser_handoff.models import (
    ClientId,
    HarnessState,
    JourneyPhase,
    PeerKind,
    PeerObservation,
)
_REQUIRED_CAPTURES: Final = (
    "viewer-a.png",
    "viewer-b.png",
    "tui-a.svg",
    "tui-b.svg",
)


@dataclass(frozen=True, slots=True)
class AcceptanceEvidenceError(ValueError):
    reason: str

    def __str__(self) -> str:
        return self.reason


class _JourneyResult(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    client: ClientId
    phases: tuple[JourneyPhase, ...]
    success: bool
    cleanup_completed: bool


def _require_artifact(root: Path, name: str) -> Path:
    path = root / name
    if not path.is_file() or path.stat().st_size == 0:
        raise AcceptanceEvidenceError(f"missing or empty artifact: {name}")
    return path


def validate_acceptance_evidence(root: Path) -> HarnessState:
    """Validate the complete machine-evidence bundle before publication."""
    expected_phases = tuple(JourneyPhase)
    reports = tuple(
        _JourneyResult.model_validate_json(
            _require_artifact(root, f"client-{client.value}.json").read_text()
        )
        for client in ClientId
    )
    for report in reports:
        if not report.success or not report.cleanup_completed:
            raise AcceptanceEvidenceError(
                f"client {report.client.value} did not complete cleanly"
            )
        if report.phases != expected_phases:
            raise AcceptanceEvidenceError(
                f"client {report.client.value} recorded an incomplete journey"
            )
    state = HarnessState.model_validate_json(
        _require_artifact(root, "backend-state.json").read_text()
    )
    JourneyEvidence(peers=state.peers).validate_distinct_client_peers()
    if state.run_id != RUN_ID or state.checkpoint != CHECKPOINT:
        raise AcceptanceEvidenceError("backend identity does not match the seeded run")
    if state.sentinel != SENTINEL_VALUE or state.fresh_resume_sentinel != SENTINEL_VALUE:
        raise AcceptanceEvidenceError("fresh automation did not observe the edit sentinel")
    if state.fresh_resume_page_identity != state.page_identity:
        raise AcceptanceEvidenceError("resume observed a replacement browser page")
    if state.resume_dispatch_count != 1 or len(state.resume_receipts) != 2:
        raise AcceptanceEvidenceError("resume was not exactly-once with one replay")
    if state.resume_receipts[0] != state.resume_receipts[1]:
        raise AcceptanceEvidenceError("resume replay receipt differs from the original")
    if state.viewer_connected or state.lease_state != "released":
        raise AcceptanceEvidenceError("interactive authority remained active")
    if state.max_concurrent_viewers != 1:
        raise AcceptanceEvidenceError("more than one viewer held authority")
    for name in _REQUIRED_CAPTURES:
        _require_artifact(root, name)
    return state
